92	const buildDirectedAdjacency = (
93	  nodes: G6NodeData[],
94	  edges: G6EdgeData[]
95	): { forward: Map<string, string[]>; backward: Map<string, string[]> } => {
96	  const forward = new Map<string, string[]>();
97	  const backward = new Map<string, string[]>();
98	  nodes.forEach((n) => {
99	    forward.set(n.id, []);
100	    backward.set(n.id, []);
101	  });
102	  edges.forEach((e) => {
103	    forward.get(String(e.source))?.push(String(e.target));
104	    backward.get(String(e.target))?.push(String(e.source));
105	  });
106	
107	  return { forward, backward };
108	};
109	
110	const bfsFromNode = (
111	  adj: Map<string, string[]>,
112	  startId: string
113	): Map<string, number> => {
114	  const depth = new Map<string, number>();
115	  depth.set(startId, 0);
116	  const queue = [startId];
117	  let qi = 0;
118	  while (qi < queue.length) {
119	    const cur = queue[qi++];
120	    const d = depth.get(cur)!;
121	    for (const nbr of adj.get(cur) ?? []) {
122	      if (!depth.has(nbr)) {
123	        depth.set(nbr, d + 1);
124	        queue.push(nbr);
125	      }
126	    }
127	  }
128	
129	  return depth;
130	};
131	
132	const computeDirectedBFSPartitions = (
133	  nodes: G6NodeData[],
134	  edges: G6EdgeData[],
135	  focusNodeId: string
136	): Map<string, number> => {
137	  const { forward, backward } = buildDirectedAdjacency(nodes, edges);
138	  const backDepth = bfsFromNode(backward, focusNodeId);
139	  const fwdDepth = bfsFromNode(forward, focusNodeId);
140	
141	  let maxBack = 0;
142	  backDepth.forEach((d) => {
143	    if (d > maxBack) {
144	      maxBack = d;
145	    }
146	  });
147	
148	  const partitions = new Map<string, number>();
149	  partitions.set(focusNodeId, maxBack);
150	  // Pure predecessors only — nodes reachable in both directions participate in
151	  // cycles or cross-paths; assigning them a partition would create backward edges
152	  // in ELK's layer graph, causing a negative-index crash.
153	  backDepth.forEach((d, id) => {
154	    if (id !== focusNodeId && !fwdDepth.has(id)) {
155	      partitions.set(id, maxBack - d);
156	    }
157	  });
158	  fwdDepth.forEach((d, id) => {
159	    if (id !== focusNodeId && !backDepth.has(id)) {
160	      partitions.set(id, maxBack + d);
161	    }
162	  });
163	
164	  return partitions;
165	};
